"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["31391"],{4242(e){e.exports=JSON.parse('{"id":"FIN-400","slug":"equity-value-multiple","term":"Equity Value Multiple","also_known_as":[],"difficulty":"Intermediate","definition":"An equity value multiple is a valuation ratio that compares the value of a company\'s shares with a financial measure that belongs to shareholders, such as earnings, book value or cash flow per share.","explanation":["Equity value multiples use market capitalization, or share price, in the numerator. The denominator must match: it should be a measure that relates only to shareholders, after interest has been paid to lenders.","Common examples include the price-to-earnings ratio, which compares price with earnings per share; the price-to-book ratio, which compares price with book value per share; the price-to-sales ratio; and price-to-cash-flow ratios.","For example, a company with a share price of 60 and earnings per share of 4 has a price-to-earnings multiple of 15. If similar companies trade at 18 times earnings, the company may look relatively cheap, assuming its prospects are similar.","Equity value multiples are easy to calculate and widely quoted. However, they are affected by how a company is financed. A company with more debt pays more interest, which lowers its earnings and can distort comparisons. For this reason, analysts comparing companies with different debt levels often prefer enterprise value multiples, such as EV/EBITDA."],"note":"","total":1500,"prev":{"slug":"equity-value","term":"Equity Value"},"next":{"slug":"equivalent-annual-annuity","term":"Equivalent Annual Annuity"}}')}}]);